/** Regression coverage for GH-6051 and GH-6052. */
class EmptyInputAggregateTest {

	@ParameterizedTest
	@ValueSource(strings = { "SUM(1)", "SUM(DISTINCT 1)", "AVG(1)", "AVG(DISTINCT 1)",
			"COUNT(1)", "COUNT(DISTINCT 1)", "COUNT(*)", "COUNT(DISTINCT *)" })
	void emptyImplicitGroupHasZeroContributions(String aggregate) {
		List<BindingSet> rows = evaluate(aggregate, "?s <urn:p> ?v . ?s <urn:q> ?w .", "", false);
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).getValue("result"))
				.isEqualTo(SimpleValueFactory.getInstance().createLiteral("0", XSD.INTEGER));
	}

	@ParameterizedTest
	@ValueSource(strings = { "MIN(1)", "MAX(1)", "SAMPLE(1)", "MIN(DISTINCT 1)",
			"MAX(DISTINCT 1)", "SAMPLE(DISTINCT 1)" })
	void emptyImplicitGroupHasNoSelectedValue(String aggregate) {
		List<BindingSet> rows = evaluate(aggregate, "?s <urn:p> ?v .", "", false);
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).hasBinding("result")).isFalse();
	}

	@ParameterizedTest
	@ValueSource(strings = { "GROUP_CONCAT(\"x\")", "GROUP_CONCAT(DISTINCT \"x\")" })
	void emptyImplicitGroupDoesNotConcatenateConstant(String aggregate) {
		List<BindingSet> rows = evaluate(aggregate, "?s <urn:p> ?v .", "", false);
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).getValue("result")).isEqualTo(SimpleValueFactory.getInstance().createLiteral(""));
	}

	@ParameterizedTest
	@ValueSource(strings = { "GROUP_CONCAT(?v)", "SUM(1)", "COUNT(*)", "MAX(1)" })
	void normalizationPreservesImplicitGroupOverFalseFilter(String aggregate) {
		List<BindingSet> rows = evaluate(aggregate, "?s <urn:p> ?v . ?s <urn:q> ?w . FILTER(false)", "", true);
		assertThat(rows).hasSize(1);
		if (aggregate.startsWith("GROUP_CONCAT")) {
			assertThat(rows.get(0).getValue("result")).isEqualTo(SimpleValueFactory.getInstance().createLiteral(""));
		} else if (aggregate.startsWith("MAX")) {
			assertThat(rows.get(0).hasBinding("result")).isFalse();
		} else {
			assertThat(rows.get(0).getValue("result"))
					.isEqualTo(SimpleValueFactory.getInstance().createLiteral("0", XSD.INTEGER));
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "GROUP_CONCAT(?v)", "SUM(1)", "COUNT(*)", "MAX(1)" })
	void normalizationKeepsExplicitGroupsEmpty(String aggregate) {
		assertThat(evaluate(aggregate, "?s <urn:p> ?v . FILTER(false)", "GROUP BY ?s", true)).isEmpty();
	}

	@ParameterizedTest
	@ValueSource(strings = { "SUM(1)", "COUNT(1)", "MIN(1)", "MAX(1)" })
	void realSingletonStillContributes(String aggregate) {
		List<BindingSet> rows = evaluate(aggregate, "VALUES ?v { 7 }", "", true);
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).getValue("result"))
				.isEqualTo(SimpleValueFactory.getInstance().createLiteral("1", XSD.INTEGER));
	}

	@ParameterizedTest
	@ValueSource(strings = { "COUNT(*)", "COUNT(DISTINCT *)" })
	void realEmptyBindingSetStillCountsAsOneSolution(String aggregate) {
		List<BindingSet> rows = evaluate(aggregate, "", "", true);
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).getValue("result"))
				.isEqualTo(SimpleValueFactory.getInstance().createLiteral("1", XSD.INTEGER));
	}

	@ParameterizedTest
	@ValueSource(strings = { "?s <urn:p> ?v . ?s <urn:q> ?w .",
			"?s <urn:p> ?v . ?s <urn:q> ?w . FILTER(false)", "VALUES ?v {}" })
	void fullOptimizerPipelinePreservesEmptyAggregateResults(String body) {
		String query = "SELECT (SUM(1) AS ?sum) (AVG(1) AS ?avg) (COUNT(*) AS ?count) "
				+ "(GROUP_CONCAT(\"x\") AS ?concat) (MIN(1) AS ?min) (MAX(1) AS ?max) "
				+ "(SAMPLE(1) AS ?sample) WHERE { " + body + " }";
		List<BindingSet> rows = evaluateQuery(query, 2);
		assertThat(rows).hasSize(1);
		BindingSet row = rows.get(0);
		assertThat(row.getBindingNames()).containsExactlyInAnyOrder("sum", "avg", "count", "concat");
		for (String name : List.of("sum", "avg", "count")) {
			assertThat(row.getValue(name))
					.isEqualTo(SimpleValueFactory.getInstance().createLiteral("0", XSD.INTEGER));
		}
		assertThat(row.getValue("concat")).isEqualTo(SimpleValueFactory.getInstance().createLiteral(""));
	}

	@ParameterizedTest
	@ValueSource(strings = { "SELECT (SUM(1) AS ?result) WHERE { VALUES ?v {} } GROUP BY ?v",
			"SELECT (COUNT(*) AS ?result) WHERE { FILTER(false) } HAVING(COUNT(*) > 0)",
			"SELECT (GROUP_CONCAT(?v) AS ?result) WHERE { FILTER(false) } GROUP BY ?v" })
	void fullOptimizerPipelinePreservesEmptyResults(String query) {
		assertThat(evaluateQuery(query, 2)).isEmpty();
	}

	private List<BindingSet> evaluate(String aggregate, String body, String grouping, boolean normalize) {
		String query = "SELECT (" + aggregate + " AS ?result) WHERE { " + body + " } " + grouping;
		return evaluateQuery(query, normalize ? 1 : 0);
	}

	private List<BindingSet> evaluateQuery(String query, int optimizationMode) {
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		// SailSourceConnection also clones the parsed tree before optimization.
		var root = new QueryRoot(parsed.getTupleExpr().clone());
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		if (optimizationMode == 1) {
			new QueryModelNormalizerOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
		} else if (optimizationMode == 2) {
			strategy.optimize(root, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		}
		List<BindingSet> rows = new ArrayList<>();
		try (var result = strategy.precompile(root).evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}
}
